function validate(input) {
  const [{ Visits = [], Transactions = [] }] = input;
  const visits = new Set(), transactions = new Set();
  for (const [visit, customer] of Visits) {
    if (visit === null || customer === null) return 'Every visit needs a visit_id and a customer_id.';
    if (visits.has(visit)) return `visit_id ${visit} appears twice in Visits.`;
    visits.add(visit);
  }
  for (const [id, visit] of Transactions) {
    if (id === null || visit === null) return 'Every transaction needs a transaction_id and a visit_id.';
    if (transactions.has(id)) return `transaction_id ${id} appears twice in Transactions.`;
    transactions.add(id);
  }
  return null;
}

