function generate(rand, size) {
  const small = size === 'small';
  const visitCount = small ? Math.floor(rand() * 9) : 1500;
  const customers = small ? 3 : 300;
  const Visits = [], Transactions = [];
  for (let id = 1; id <= visitCount; id++) Visits.push([id, 10 + Math.floor(rand() * customers)]);
  // Transactions land on existing visits (often several on one visit) or on visit ids missing from Visits.
  const transactionCount = small ? Math.floor(rand() * 9) : 2000;
  for (let id = 1; id <= transactionCount; id++) {
    const visit = 1 + Math.floor(rand() * (visitCount + (small ? 3 : 200)));
    Transactions.push([id, visit, 1 + Math.floor(rand() * 1000)]);
  }
  return [{ Visits, Transactions }];
}
